// The pane's formatter (stage 4, #1283; narrowed in #885): src/transcript-format.js
// renders a stream-json event as prose, a one-line tool call or a result line,
// and nothing else.
//
// The checked-in fixture -> checked-in expected output, asserted always.
// fixture-transcript.jsonl is synthetic events in the shapes of a Smith's run
// logs (generic paths and text, a redacted thinking signature) plus the two shapes a
// healthy run never produces: a usage-limit `result` and a Codex
// `item.completed`. fixture-transcript.expected.txt was generated by
// observe.py while it existed; since #885 it is the pane's own contract.
"use strict";
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { formatLines, formatEvent, truncate, jqNum, jqRound, limitNote, endLabel } =
  require("../src/transcript-format");

const HERE = path.join(__dirname, "..");
const fixturePath = path.join(HERE, "fixture-transcript.jsonl");
const raw = fs.readFileSync(fixturePath, "utf8");
const lines = raw.split("\n").filter(Boolean);
const expected = fs.readFileSync(path.join(HERE, "fixture-transcript.expected.txt"), "utf8")
  .replace(/\n$/, "").split("\n\n");

test("the fixture covers the event shapes smith-tail renders", () => {
  const types = lines.map((l) => JSON.parse(l)).map((e) =>
    e.type === "assistant"
      ? ((e.message || {}).content || []).map((c) => c.type).join("+")
      : `${e.type}${e.subtype ? `:${e.subtype}` : ""}`);
  assert.ok(types.includes("system:init"), "a session init, which renders to nothing");
  assert.ok(lines.map((l) => JSON.parse(l)).some((e) => e.type === "user" &&
    ((e.message || {}).content || []).some((c) => c.type === "tool_result")),
  "a user tool_result event, which renders to nothing");
  assert.ok(types.some((t) => t.includes("text")), "an assistant text event");
  assert.ok(types.some((t) => t.includes("tool_use")), "a tool call");
  assert.ok(types.includes("thinking"), "a thinking-only event, which renders to nothing");
  assert.ok(types.filter((t) => t.startsWith("result")).length >= 2, "a clean and a failed result");
  assert.ok(types.includes("item.completed"), "a Codex event");
});

test("the fixture renders exactly the smith-tail lines", () => {
  // One entry per item; the expected file puts a blank line between entries
  // (#934), and a result event's entry carries its own `↳` newline.
  const got = formatLines(lines);
  assert.deepEqual(got, expected);
});

test("tool_use, text and result each render in their own shape", () => {
  const byType = (pred) => lines.map((l) => JSON.parse(l)).filter(pred);
  const tool = byType((e) => ((e.message || {}).content || []).some((c) => c.type === "tool_use"))[0];
  const text = byType((e) => ((e.message || {}).content || []).some((c) => c.type === "text"))[0];
  const results = byType((e) => e.type === "result");

  // tool call: "→ <Name>  <description, ≤100 cp>", no raw JSON
  const toolLine = formatEvent(tool)[0];
  assert.match(toolLine, /^→ \w+ {2}[^{\s]/);
  // assistant text: no time column, no arrow, whitespace collapsed
  const textLine = formatEvent(text)[0];
  assert.match(textLine, /^[^→─\s\d]/);
  assert.ok(!/\n/.test(textLine) && !/ {3}/.test(textLine), "text is collapsed to one line");
  // result: the "── result:" rule, with the is_error detail on its own line
  assert.match(formatEvent(results[0])[0], /── result: success · \d+ turns · \d+s · ~\$/);
  const failed = formatEvent(results.find((e) => e.is_error))[0];
  assert.match(failed, /── result: success · is_error · /);
  assert.match(failed, /\n {3}↳ Claude AI usage limit reached · resets 5:40am \(UTC\)$/);

  // a thinking-only event renders to nothing at all, as on the host
  const thinking = byType((e) => e.type === "assistant" &&
    ((e.message || {}).content || []).every((c) => c.type === "thinking"))[0];
  assert.deepEqual(formatEvent(thinking), []);
});

const TS = "2026-09-21T03:17:05.144Z";
const toolEvent = (name, input) => ({ type: "assistant", timestamp: TS,
  message: { content: [{ type: "tool_use", id: "t1", name, input }] } });

test("a tool call is one line: name and description", () => {
  const bash = formatEvent(toolEvent("Bash", { command: "ls -la", description: "List files in the repo" }));
  assert.equal(bash.length, 1);
  assert.match(bash[0], /^→ Bash {2}List files in the repo$/);
  assert.ok(!bash[0].includes("{"));
  const read = formatEvent(toolEvent("Read", { file_path: "/work/repo/README.md" }));
  assert.equal(read.length, 1);
  assert.ok(read[0].endsWith("→ Read  /work/repo/README.md"));
  const bare = formatEvent(toolEvent("TodoWrite", {}));
  assert.equal(bare.length, 1);
  assert.ok(bare[0].endsWith("→ TodoWrite") && !/\s$/.test(bare[0]));
  const long = formatEvent(toolEvent("Agent", { description: "x".repeat(150) }))[0];
  const desc = long.split("→ Agent  ")[1];
  assert.equal(Array.from(desc).length, 101);
  assert.ok(desc.endsWith("…") && desc.startsWith("x".repeat(100)));
});

test("init, thinking and tool results render nothing", () => {
  assert.deepEqual(formatEvent({ type: "system", subtype: "init", session_id: "abc", model: "m" }), []);
  assert.deepEqual(formatEvent({ type: "user", timestamp: TS,
    message: { content: [{ type: "tool_result", tool_use_id: "t1", content: "ok" }] } }), []);
  assert.deepEqual(formatEvent({ type: "assistant", timestamp: TS,
    message: { content: [{ type: "thinking", thinking: "hmm" }] } }), []);
  assert.deepEqual(formatEvent({ type: "rate_limit_event" }), []);
});

test("an account-limit result still carries its limit note and end label", () => {
  const failed = lines.map((l) => JSON.parse(l))
    .find((e) => e.type === "result" && e.is_error);
  assert.equal(limitNote(failed), "the Claude account hit a usage limit (resets 5:40am (UTC))");
  assert.equal(endLabel(failed), "(usage limit reached · resets 5:40am (UTC))");
});

test("the jq-isms the port exists to preserve", () => {
  // an integral float prints without a trailing .0, like jq's number printer
  assert.equal(jqNum(3.0), "3");
  assert.equal(jqNum(2.7253), "2.7253");
  assert.equal(jqNum(null), "null");
  // round is half away from zero, not Math.round's half up
  assert.equal(jqRound(-0.5), -1);
  assert.equal(jqRound(0.5), 1);
  // truncate counts code points, so an emoji is one character and not two
  assert.equal(truncate("🤖🤖🤖", 2), "🤖🤖…");
  assert.equal(truncate("abc", 3), "abc");
  // non-JSON lines are dropped before parsing, as the shell's `grep '^{'` does
  assert.deepEqual(formatLines(["── following /var/log/x.log", "not json", ""]), []);
});

